B.agf=new A.cQ("\u0625\u062f\u063a\u0627\u0645 \u0627\u0644\u0645\u062a\u062c\u0627\u0646\u0633\u064a\u0646","\u062d\u0631\u0641\u0627\u0646 \u0645\u0646 \u0645\u062e\u0631\u062c \u0648\u0627\u062d\u062f\u060c \u0627\u0644\u0623\u0648\u0644 \u0633\u0627\u0643\u0646\u060c \u0641\u064a\u064f\u062f\u063a\u0645 \u0627\u0644\u0623\u0648\u0644 \u0641\u064a \u0627\u0644\u062b\u0627\u0646\u064a.",u.V)
