B.a8r=new A.W(B.bE,[B.ag6,B.afT],t.d)
B.ag9=new A.cQ("\u0627\u0644\u0642\u0644\u0642\u0644\u0629","\u062d\u0631\u0648\u0641 (\u0642\u0637\u0628 \u062c\u062f) \u0625\u0630\u0627 \u0633\u0643\u0646\u062a \u062a\u064f\u0646\u0637\u0642 \u0628\u0635\u0648\u062a \u0627\u0631\u062a\u062f\u0627\u062f\u064a \u062e\u0641\u064a\u0641.","\u0627\u062c\u0639\u0644 \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u0633\u0627\u0643\u0646 \u064a\u0631\u062a\u062f \u0628\u0635\u0648\u062a \u062e\u0641\u064a\u0641 \u062f\u0648\u0646 \u0623\u0646 \u062a\u0636\u064a\u0641 \u0625\u0644\u064a\u0647 \u062d\u0631\u0643\u0629.")
B.agg=new A.cQ("Qalqalah (echo)","The letters qaaf, taa, baa, jeem and daal with sukoon are pronounced with a light bounce.","Let the letter bounce slightly without adding a vowel.")
B.a8m=new A.W(B.bE,[B.ag9,B.agg],t.d)
B.afX=new A.cQ("\u0627\u0644\u0645\u062f \u0627\u0644\u0637\u0628\u064a\u0639\u064a","\u062d\u0631\u0648\u0641 \u0627\u0644\u0645\u062f (\u0627 \u0648 \u064a) \u062a\u064f\u0645\u062f \u0628\u0645\u0642\u062f\u0627\u0631 \u062d\u0631\u0643\u062a\u064a\u0646.","\u0645\u062f\u0651 \u0627\u0644\u0635\u0648\u062a \u062d\u0631\u0643\u062a\u064a\u0646 \u0641\u0642\u0637\u060c \u0644\u0627 \u0623\u0642\u0644 \u0648\u0644\u0627 \u0623\u0643\u062b\u0631.")
B.afW=new A.cQ("Natural madd","The madd letters alif, waw and yaa are lengthened for two counts.","Stretch the sound for exactly two counts.")
B.a8p=new A.W(B.bE,[B.afX,B.afW],t.d)
B.afU=new A.cQ("\u0627\u0644\u0645\u062f \u0627\u0644\u062c\u0627\u0626\u0632","\u0645\u062f\u064c\u0651 \u064a\u062c\u0648\u0632 \u0641\u064a\u0647 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0645\u0642\u062f\u0627\u0631 \u062d\u0633\u0628 \u0646\u0648\u0639\u0647\u060c \u0645\u062b\u0644 \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0648\u0627\u0644\u0639\u0627\u0631\u0636 \u0644\u0644\u0633\u0643\u0648\u0646.","\u0627\u0644\u062a\u0632\u0645 \u0645\u0642\u062f\u0627\u0631\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0641\u064a \u062a\u0644\u0627\u0648\u062a\u0643 \u0643\u0644\u0647\u0627\u060c \u0643\u0645\u0627 \u062a\u0633\u0645\u0639\u0647 \u0645\u0646 \u0627\u0644\u0642\u0627\u0631\u0626.")
B.ag8=new A.cQ("Permissible madd","A madd that may be lengthened by more than one amount depending on its type, such as munfasil or aarid.","Keep one length throughout your recitation, as you hear from the reciter.")
B.a8j=new A.W(B.bE,[B.afU,B.ag8],t.d)
B.afR=new A.cQ("\u0627\u0644\u0645\u062f \u0627\u0644\u0648\u0627\u062c\u0628 \u0627\u0644\u0645\u062a\u0635\u0644","\u062d\u0631\u0641 \u0645\u062f \u0628\u0639\u062f\u0647 \u0647\u0645\u0632\u0629 \u0641\u064a \u0627\u0644\u0643\u0644\u0645\u0629 \u0646\u0641\u0633\u0647\u0627\u060c \u0648\u064a\u064f\u0645\u062f \u0623\u0631\u0628\u0639 \u0623\u0648 \u062e\u0645\u0633 \u062d\u0631\u0643\u0627\u062a.","\u0644\u0627 \u062a\u0642\u0635\u0631 \u0647\u0630\u0627 \u0627\u0644\u0645\u062f\u061b \u0623\u0637\u0650\u0644\u0647 \u0642\u0628\u0644 \u0646\u0637\u0642 \u0627\u0644\u0647\u0645\u0632\u0629.")
B.agb=new A.cQ("Obligatory madd (muttasil)","A madd letter followed by hamza in the same word, lengthened for four or five counts.","Don't shorten it; stretch it before saying the hamza.")
B.a8t=new A.W(B.bE,[B.afR,B.agb],t.d)
B.age=new A.cQ("\u0627\u0644\u0645\u062f \u0627\u0644\u0644\u0627\u0632\u0645","\u062d\u0631\u0641 \u0645\u062f \u0628\u0639\u062f\u0647 \u0633\u0643\u0648\u0646 \u0623\u0635\u0644\u064a\u060c \u0648\u064a\u064f\u0645\u062f \u0633\u062a \u062d\u0631\u0643\u0627\u062a.","\u0645\u062f\u0651\u0647 \u0633\u062a \u062d\u0631\u0643\u0627\u062a \u0643\u0627\u0645\u0644\u0629.")
B.afZ=new A.cQ("Necessary madd (lazim)","A madd letter followed by an original sukoon, lengthened for six counts.","Stretch it for a full six counts.")
B.a8k=new A.W(B.bE,[B.age,B.afZ],t.d)
B.aga=new A.cQ("\u0627\u0644\u0644\u0627\u0645 \u0627\u0644\u0634\u0645\u0633\u064a\u0629","\u0644\u0627\u0645 \xab\u0627\u0644\xbb \u0642\u0628\u0644 \u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0634\u0645\u0633\u064a\u0629 \u0644\u0627 \u062a\u064f\u0646\u0637\u0642\u060c \u0648\u064a\u064f\u0634\u062f\u064e\u0651\u062f \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u0630\u064a \u0628\u0639\u062f\u0647\u0627.","\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u0644\u0627\u0645 \u0648\u0627\u0646\u0637\u0642 \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u062a\u0627\u0644\u064a \u0645\u0634\u062f\u062f\u0627\u064b.")
